import{_ as n,y as r,a as s,o as i,a2 as a,D as o}from"./chunks/framework.DCcmcJcL.js";const m=JSON.parse('{"title":"Cache Management","description":"","frontmatter":{},"headers":[],"relativePath":"configure/cache-management.md","filePath":"configure/cache-management.md","lastUpdated":1789395222000}'),c={name:"configure/cache-management.md"};function l(h,e,g,u,d,p){const t=r("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=a('<h1 id="cache-management" tabindex="-1">Cache Management <a class="header-anchor" href="#cache-management" aria-label="Permalink to &quot;Cache Management&quot;">​</a></h1><p>Cache Management lets you clear and rebuild the caches your store keeps, and switch the storefront&#39;s full page cache on or off. It has two screens, <strong>General</strong> and <strong>Full Page Cache</strong>.</p><h2 id="clear-or-build-caches" tabindex="-1">Clear or build caches <a class="header-anchor" href="#clear-or-build-caches" aria-label="Permalink to &quot;Clear or build caches&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Cache Management &gt;&gt; General</strong>.</li><li>In <strong>Cache Actions</strong>, click the button for the action you want.</li><li>Read the result in the <strong>Output Console</strong> below the buttons.</li></ol>',4)),o(t,{src:"/images/configure/cache-management-actions.png",alt:"Cache Actions section with the Clear Cache and Build Cache buttons and the Output Console"}),e[1]||(e[1]=a('<p>The buttons act straight away; there is nothing to save.</p><p>Under <strong>Clear Cache</strong>, each button removes one kind of cached data, so the store builds it again on the next request:</p><ul><li><strong>Clear All Cache</strong> – every cache below at once.</li><li><strong>Clear Config Cache</strong> – the cached configuration.</li><li><strong>Clear Application Cache</strong> – the application cache.</li><li><strong>Clear Compiled Cache</strong> – compiled classes and files.</li><li><strong>Clear Event Cache</strong> – cached event data.</li><li><strong>Clear Route Cache</strong> – cached routes.</li><li><strong>Clear View Cache</strong> – compiled page templates.</li><li><strong>Clear Page Cache</strong> – the storefront&#39;s full page cache, the same as <strong>Flush Page Cache</strong> below.</li></ul><p>Under <strong>Build Cache</strong>, each button builds a cache in advance, so the store starts fast after an update:</p><ul><li><strong>Rebuild All Cache</strong> – every cache below at once.</li><li><strong>Cache Config</strong> – the configuration.</li><li><strong>Cache Routes</strong> – the routes.</li><li><strong>Cache Views</strong> – the page templates.</li></ul><h3 id="important-notes" tabindex="-1">Important notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to &quot;Important notes&quot;">​</a></h3><ul><li>Caching routes fails when a route is written as a closure rather than pointing to a controller. The output names the route.</li><li>Caching the configuration fails when a configuration file contains a closure.</li><li>A file permission problem on the server stops both clearing and building.</li><li>After you clear a cache, the first few pages load a little more slowly while the store builds it again. Building the caches after an update avoids that.</li></ul><h2 id="full-page-cache" tabindex="-1">Full page cache <a class="header-anchor" href="#full-page-cache" aria-label="Permalink to &quot;Full page cache&quot;">​</a></h2><p>The full page cache keeps a rendered copy of your storefront pages and serves it to the next visitor, instead of building the page again for each one. It decides how quickly your storefront responds under load. The home page, category pages, product pages, search results and CMS pages are cached; the cart, checkout and account pages never are.</p><ol><li>Go to <strong>Configure &gt;&gt; Cache Management &gt;&gt; Full Page Cache</strong>.</li><li>In <strong>Settings</strong>, switch <strong>Enable Full Page Cache</strong> on or off. It is on by default.</li><li>Enter the <strong>Cache Lifetime (Minutes)</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',10)),o(t,{src:"/images/configure/full-page-cache.png",alt:"Full Page Cache screen with the page cache turned on"}),e[2]||(e[2]=a('<p><strong>Enable Full Page Cache:</strong> Serves storefront pages from the cache. Turning it off renders every page again on each visit, which is slower for shoppers but useful while you check a page that looks out of date.</p><p><strong>Cache Lifetime (Minutes):</strong> How long a cached page is kept before it is rendered again. The default is <code>10080</code>, one week. Leave it empty to use the application default.</p><p><strong>Flush Page Cache:</strong> Empties the page cache, so every storefront page is rendered again on its next visit. The button acts straight away. Use it after a change the store doesn&#39;t pick up on its own, such as a template edited on the server.</p><h3 id="you-don-t-have-to-clear-the-cache-after-an-edit" tabindex="-1">You don&#39;t have to clear the cache after an edit <a class="header-anchor" href="#you-don-t-have-to-clear-the-cache-after-an-edit" aria-label="Permalink to &quot;You don&#39;t have to clear the cache after an edit&quot;">​</a></h3><p>A cached page is refreshed automatically when the content behind it changes. Saving a product, category, review, CMS page, URL rewrite, channel, theme section or configuration clears the affected pages, and so do orders, refunds and price or catalog rule reindexing. Editing a product or a category also clears your home page and category listings, in every channel, language and currency. Each currency and language has its own copy of every page, so switching between them never shows an out-of-date page.</p><p>The lifetime is a backstop rather than the main mechanism, so set it long and let the automatic refresh handle day-to-day edits. A short lifetime doesn&#39;t fix a page that looks out of date, it only shortens how long the wrong page is shown. If a change doesn&#39;t appear at all, check that it was saved or published, then click <strong>Flush Page Cache</strong>.</p><h2 id="differences-in-bagisto-2-4" tabindex="-1">Differences in Bagisto 2.4 <a class="header-anchor" href="#differences-in-bagisto-2-4" aria-label="Permalink to &quot;Differences in Bagisto 2.4&quot;">​</a></h2><p>In Bagisto 2.4, <strong>Cache Lifetime (Minutes)</strong> has no preset value, so the application default is used until you enter one.</p>',8))])}const C=n(c,[["render",l]]);export{m as __pageData,C as default};
